import { useMemo, useState } from "react";

import { isUnderserved } from "../../lib/odi";
import { useStudio } from "../../state/StudioContext";
import { GhostMetrics, GhostOpportunityCards } from "../Skeletons";
import { OutcomeCard } from "./OutcomeCard";

export function OpportunityLandscape() {
  const { canvas, canvasLoading } = useStudio();
  const [underservedOnly, setUnderservedOnly] = useState(false);
  const [sorted, setSorted] = useState(false);

  const jobs = canvas?.jobs ?? [];
  const outcomes = useMemo(() => canvas?.outcomes ?? [], [canvas]);

  const underservedCount = outcomes.filter((outcome) =>
    isUnderserved(outcome.opportunity_score),
  ).length;

  const visible = useMemo(() => {
    const filtered = underservedOnly
      ? outcomes.filter((outcome) => isUnderserved(outcome.opportunity_score))
      : [...outcomes];
    if (sorted) {
      filtered.sort(
        (a, b) => (b.opportunity_score ?? -Infinity) - (a.opportunity_score ?? -Infinity),
      );
    }
    return filtered;
  }, [outcomes, underservedOnly, sorted]);

  return (
    <section className="stack">
      {canvasLoading && !canvas ? (
        <GhostMetrics />
      ) : (
        <div className="metrics">
          <div className="metric">
            <span className="metric__label">Jobs</span>
            <span className="metric__value">{jobs.length}</span>
          </div>
          <div className="metric">
            <span className="metric__label">Underserved</span>
            <span className="metric__value">{underservedCount}</span>
          </div>
          <div className="metric">
            <span className="metric__label">Outcomes</span>
            <span className="metric__value">{outcomes.length}</span>
          </div>
        </div>
      )}

      <div className="chips" role="group" aria-label="Filters">
        <button
          type="button"
          className={`chip${sorted ? " is-on" : ""}`}
          aria-pressed={sorted}
          onClick={() => setSorted((prev) => !prev)}
        >
          Highest score first
        </button>
        <button
          type="button"
          className={`chip${underservedOnly ? " is-on" : ""}`}
          aria-pressed={underservedOnly}
          onClick={() => setUnderservedOnly((prev) => !prev)}
        >
          Underserved only
        </button>
      </div>

      {canvasLoading && !canvas ? (
        <GhostOpportunityCards />
      ) : visible.length ? (
        <div className="cards">
          {visible.map((outcome, index) => (
            <OutcomeCard outcome={outcome} key={outcome.id ?? index} />
          ))}
        </div>
      ) : (
        <p className="empty-note">
          Nothing here yet. Ask the studio to capture an outcome, and it will appear on this
          landscape.
        </p>
      )}
    </section>
  );
}

