import { useState } from "react";

import { useStudio } from "../../state/StudioContext";
import { GhostJobSteps } from "../Skeletons";

const PHASES = [
  "Define",
  "Locate",
  "Prepare",
  "Confirm",
  "Execute",
  "Monitor",
  "Modify",
  "Conclude",
];

export function JobMap() {
  const { canvas, canvasLoading, addStep } = useStudio();
  const [stepName, setStepName] = useState("");
  const [stepOrder, setStepOrder] = useState<number | null>(null);
  const [busy, setBusy] = useState(false);

  const steps = canvas?.steps ?? [];
  const jobs = canvas?.jobs ?? [];
  const activeJobId = jobs[0]?.id ?? "JOB-402";
  const defaultOrder = steps.length + 1;

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    if (!stepName.trim() || busy) {
      return;
    }
    setBusy(true);
    try {
      await addStep({ job_id: activeJobId, name: stepName.trim(), order: stepOrder ?? defaultOrder });
      setStepName("");
      setStepOrder(null);
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="stack">
      <ol className="phases" aria-label="Universal job map phases">
        {PHASES.map((phase, index) => (
          <li className="phase" key={phase}>
            <span className="phase__index">{index + 1}</span>
            {phase}
          </li>
        ))}
      </ol>

      {canvasLoading && !canvas ? (
        <GhostJobSteps />
      ) : steps.length ? (
        <ol className="steps">
          {steps.map((step, index) => (
            <li className="step" key={step.id ?? index}>
              <span className="step__order">{step.order ?? index + 1}</span>
              {step.name ?? ""}
            </li>
          ))}
        </ol>
      ) : (
        <p className="empty-note">
          No steps yet. Walk the studio through the job and it will decompose it into these eight
          phases.
        </p>
      )}

      <details className="disclosure">
        <summary>Add a step</summary>
        <form onSubmit={submit} className="form">
          <div className="field">
            <label htmlFor="step-name">What happens in this step?</label>
            <input
              id="step-name"
              className="input"
              placeholder="Prepare the secrets payload"
              value={stepName}
              onChange={(event) => setStepName(event.target.value)}
            />
          </div>
          <div className="field">
            <label htmlFor="step-order">Position in the job</label>
            <input
              id="step-order"
              className="input"
              type="number"
              min={1}
              max={20}
              value={stepOrder ?? defaultOrder}
              onChange={(event) => setStepOrder(Number(event.target.value))}
            />
          </div>
          <button type="submit" className="button" disabled={busy || !stepName.trim()}>
            Add step
          </button>
        </form>
      </details>
    </section>
  );
}

