import { apiUrl } from "../bridge/desktopBridge";
import type {
  AddOutcomePayload,
  AddStepPayload,
  CanvasData,
  ChatStreamRequest,
  LlmHealth,
  McpHealth,
  StudioConfig,
} from "../types";
import { createSseParser, type RawSseEvent } from "./sse";

async function errorDetail(response: Response): Promise<string> {
  try {
    const body = (await response.json()) as { detail?: string };
    return body.detail ?? `Request failed (${response.status})`;
  } catch {
    return `Request failed (${response.status})`;
  }
}

async function getJson<T>(path: string): Promise<T> {
  const response = await fetch(apiUrl(path), { headers: { Accept: "application/json" } });
  if (!response.ok) {
    throw new Error(await errorDetail(response));
  }
  return (await response.json()) as T;
}

async function postJson<T>(path: string, body: unknown): Promise<T> {
  const response = await fetch(apiUrl(path), {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    body: JSON.stringify(body),
  });
  if (!response.ok) {
    throw new Error(await errorDetail(response));
  }
  return (await response.json()) as T;
}

export async function fetchConfig(): Promise<StudioConfig> {
  const body = await getJson<{ defaults: StudioConfig }>("/api/config");
  return body.defaults;
}

export function fetchCanvas(mcpUrl: string): Promise<CanvasData> {
  return getJson<CanvasData>(`/api/canvas?mcp_url=${encodeURIComponent(mcpUrl)}`);
}

export function healthMcp(mcpUrl: string): Promise<McpHealth> {
  return postJson<McpHealth>("/api/health/mcp", { mcp_url: mcpUrl });
}

export function healthLlm(config: {
  base_url: string;
  api_key: string;
  model: string;
}): Promise<LlmHealth> {
  return postJson<LlmHealth>("/api/health/llm", config);
}

export function addStep(payload: AddStepPayload): Promise<{ ok: boolean; result: string }> {
  return postJson<{ ok: boolean; result: string }>("/api/steps", payload);
}

export function addOutcome(
  payload: AddOutcomePayload,
): Promise<{ ok: boolean; result: string }> {
  return postJson<{ ok: boolean; result: string }>("/api/outcomes", payload);
}

export type ChatEventHandler = (event: RawSseEvent) => void;

export async function streamChat(
  request: ChatStreamRequest,
  onEvent: ChatEventHandler,
  signal?: AbortSignal,
): Promise<void> {
  const response = await fetch(apiUrl("/api/chat"), {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "text/event-stream" },
    body: JSON.stringify(request),
    signal,
  });

  if (!response.ok || !response.body) {
    throw new Error(await errorDetail(response));
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  const parser = createSseParser();

  for (;;) {
    const { value, done } = await reader.read();
    if (done) {
      break;
    }
    for (const event of parser.push(decoder.decode(value, { stream: true }))) {
      onEvent(event);
    }
  }
}

"""FastAPI router exposing the Living Studio sidecar API under ``/api``."""

from __future__ import annotations

from fastapi import APIRouter, Query
from fastapi.responses import StreamingResponse

from local_server.studio.chat import stream_chat
from local_server.studio.mcp_data import call_mcp_tool, fetch_canvas
from local_server.studio.probes import check_llm_health, defaults, is_endpoint_reachable
from local_server.studio.schemas import (
    AddOutcomeRequest,
    AddStepRequest,
    ChatRequest,
    LlmHealthRequest,
    McpHealthRequest,
)

router = APIRouter(prefix="/api")


@router.get("/config")
def get_config() -> dict:
    return {"defaults": defaults()}


@router.post("/health/mcp")
def post_mcp_health(body: McpHealthRequest) -> dict:
    return {"reachable": is_endpoint_reachable(body.mcp_url)}


@router.post("/health/llm")
async def post_llm_health(body: LlmHealthRequest) -> dict:
    healthy, message = await check_llm_health(body.base_url, body.api_key, body.model)
    return {"healthy": healthy, "message": message}


@router.get("/canvas")
async def get_canvas(mcp_url: str = Query(...)) -> dict:
    return await fetch_canvas(mcp_url)


@router.post("/steps")
async def post_step(body: AddStepRequest) -> dict:
    result = await call_mcp_tool(
        body.mcp_url,
        "add_step",
        {"job_id": body.job_id, "name": body.name, "order": body.order},
    )
    return {"ok": True, "result": result}


@router.post("/outcomes")
async def post_outcome(body: AddOutcomeRequest) -> dict:
    result = await call_mcp_tool(
        body.mcp_url,
        "add_outcome",
        {
            "job_id": body.job_id,
            "statement": body.statement,
            "importance": body.importance,
            "satisfaction": body.satisfaction,
        },
    )
    return {"ok": True, "result": result}


@router.post("/chat")
async def post_chat(body: ChatRequest) -> StreamingResponse:
    return StreamingResponse(
        stream_chat(body),
        media_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )

